/**
 * Provider verification — verifies the real DummyJSON API honours the contracts
 * generated by the consumer tests. Run AFTER consumer tests have generated pacts/.
 */

const { Verifier } = require('@pact-foundation/pact');
const path = require('path');

describe('Users API — Provider verification', () => {
  it('honours all consumer contracts', () => {
    return new Verifier({
      providerBaseUrl: 'https://dummyjson.com',
      pactUrls: [
        path.resolve(__dirname, '..', 'pacts', 'FrontendApp-UsersAPI.json'),
      ],
      logLevel: 'warn',
      // DummyJSON (behind Cloudflare) returns brotli-compressed bodies when the client
      // allows it, and the verifier then fails to parse them. Ask for plain JSON.
      customProviderHeaders: ['Accept-Encoding: identity'],
      // State handlers: map consumer state descriptions to provider setup steps.
      // DummyJSON is a public read-only API so no setup is needed here.
      stateHandlers: {
        'users exist':               () => Promise.resolve(),
        'user with id 1 exists':     () => Promise.resolve(),
        'user with id 9999 does not exist': () => Promise.resolve(),
      },
    }).verifyProvider();
  });
});
